WITH focal AS (SELECT REPLACE(id_imovel,'-','') id_car_norm FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE id_imovel='BA-2929701-3438EBE3EC1C4160B13A7DC99112E048' AND data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2019 AND 2024),fp AS (SELECT DISTINCT p.id_referencia_bacen,p.numero_ordem,p.ano_emissao FROM p JOIN focal USING(id_car_norm)),ag AS (SELECT DISTINCT id_referencia_bacen,numero_ordem,cnpj_agencia FROM `basedosdados.br_bcb_sicor.recurso_publico_complemento_operacao` WHERE ano_emissao BETWEEN 2019 AND 2024) SELECT ag.cnpj_agencia,e.cnpj,e.nome_fantasia,e.id_municipio,e.sigla_uf,e.logradouro,e.numero,e.bairro,COUNT(*) ordens FROM fp JOIN ag USING(id_referencia_bacen,numero_ordem) LEFT JOIN `basedosdados.br_bd_diretorios_brasil.empresa` e ON e.cnpj=ag.cnpj_agencia GROUP BY 1,2,3,4,5,6,7,8 ORDER BY ordens DESC